trustedTypes:
/* Lumen: Trusted Types default policy for the webR worker */
if (typeof self !== "undefined" && self.trustedTypes && !self.trustedTypes.defaultPolicy) {
  try {
    self.trustedTypes.createPolicy("default", {
      createScriptURL: function (u) {
        var url = new URL(u, self.location.href);
        if (url.origin !== self.location.origin) throw new TypeError("Blocked cross-origin script: " + u);
        return u;
      },
      createScript: function (s) { return s; },
    });
  } catch (e) { /* policy name not allowed: leave as is */ }
}

